1	package com.fream.back.domain.shipment.config;
2	
3	import com.fream.back.domain.notification.service.command.NotificationCommandService;
4	import com.fream.back.domain.shipment.entity.OrderShipment;
5	import com.fream.back.domain.shipment.entity.ShipmentStatus;
6	import com.fream.back.domain.shipment.exception.ShipmentErrorCode;
7	import com.fream.back.domain.shipment.exception.ShipmentException;
8	import com.fream.back.domain.shipment.repository.OrderShipmentRepository;
9	import com.fream.back.domain.shipment.service.command.OrderShipmentCommandService;
10	import com.fream.back.global.utils.CjTrackingPlaywright;
11	import com.fream.back.global.utils.PlaywrightBrowserManager;
12	import jakarta.persistence.EntityManagerFactory;
13	import lombok.RequiredArgsConstructor;
14	import lombok.extern.slf4j.Slf4j;
15	import org.jsoup.Jsoup;
16	import org.jsoup.nodes.Document;
